messages.content:
Tool response:
Tool: upgrade_subscription
Description: Upgrades the specified subscription from the Basic plan to the Premium plan.
This operation updates the plan_id in the subscriptions table and applies the new pricing effective immediately.
Parameters:
    {
      "type": "object",
      "properties": {
        "subscription_id": {
          "type": "integer",
          "title": "Subscription Id",
          "description": ""
        }
      },
      "required": [
        "subscription_id"
      ]
    }

Tool response:
Tool: apply_coupon_to_subscription
Description: Applies the given coupon code to the specified subscription for the upcoming billing cycle.
Validates that the coupon is active and not expired, and records the application in the subscription_coupons table.
Parameters:
    {
      "type": "object",
      "properties": {
        "subscription_id": {
          "type": "integer",
          "title": "Subscription Id",
          "description": ""
        },
        "coupon_code": {
          "type": "string",
          "title": "Coupon Code",
          "description": ""
        }
      },
      "required": [
        "subscription_id",
        "coupon_code"
      ]
    }
